el,.country-edit-form label{display:grid;gap:6px;min-width:0;color:#bec9e8;font-size:11px;font-weight:700}.currency-edit-form label.check,.country-edit-form label.check{display:flex;align-items:center;gap:8px}.currency-edit-form button,.country-edit-form button{grid-column:1/-1}.country-summary,.country-bulk,.country-filters{display:flex;align-items:center;gap:9px;flex-wrap:wrap}.country-summary{margin-top:15px}.country-summary span{padding:9px 12px;border:1px solid var(--cc-line);border-radius:11px;background:rgba(255,255,255,.04);color:#aebbdc;font-size:11px}.country-summary strong{color:#fff}.country-filters{padding:14px;border:1px solid var(--cc-line);border-radius:14px;background:rgba(9,14,28,.33)}.country-filters>*{flex:1 1 145px;min-width:0}.country-filters button,.country-filters a{flex:0 0 auto}.country-bulk{padding:12px 14px;border:1px solid rgba(0,232,144,.15);border-radius:14px;background:rgba(0,232,144,.045)}.country-bulk>strong{margin-inline-end:auto;color:#e6edff;font-size:12px}.country-bulk>*{min-width:150px}.country-legacy{grid-column:1/-1;padding:12px;border:1px solid var(--cc-line);border-radius:10px;background:rgba(255,255,255,.025)}.country-legacy summary{margin-bottom:9px;color:#d8e1fa;font-weight:700}.country-legacy label{margin-bottom:8px}.currency-country-admin .pagination{margin-top:18px}.currency-country-admin>.row .card{border:1px solid var(--cc-line);border-radius:17px;background:linear-gradient(145deg,#1a223b,#141b30)}.currency-country-admin>.row .card-body>h5,.currency-country-admin>.card .card-body>h5{color:#f2f5ff;font-weight:800}.currency-country-admin>.row form label{display:block;margin-top:11px;color:#c1cce8;font-size:12px;font-weight:700}.currency-country-admin>.row form .form-control{margin-top:5px}
@media(max-width:767px){.cc-hero__content{padding:22px 18px}.cc-hero__footer{align-items:flex-start;flex-direction:column}.cc-hero__metrics{width:100%}.cc-hero__metrics span{flex:1;text-align:center}.cc-section-heading{align-items:flex-start}.cc-section-heading>div{align-items:flex-start}.cc-section-heading p{max-width:250px}.cc-provider-pill{display:none}.rate-source-card{align-items:flex-start;flex-direction:column}.rate-source-card form,.rate-source-card form button{width:100%}.currency-settings-panel{min-width:0}.currency-edit-form,.country-edit-form{grid-template-columns:1fr}.currency-edit-form button,.country-edit-form button,.country-legacy{grid-column:auto}.country-bulk>*{width:100%}.country-bulk>strong{width:100%}.country-filters>*{flex-basis:100%}.cc-audit-link{width:100%;justify-content:center}.currency-country-admin .table-responsive{border:1px solid var(--cc-line);border-radius:12px}.currency-country-admin .table{min-width:720px}}
</style>
<script>
document.getElementById('select-all-countries')?.addEventListener('change', event => document.querySelectorAll('.country-row-check').forEach(input => input.checked = event.target.checked));
const bulkAction=document.getElementById('country-bulk-action'), bulkCurrency=document.getElementById('bulk-currency');
function syncBulkCurrency(){if(bulkCurrency)bulkCurrency.hidden=bulkAction?.value!=='set_currency'}
bulkAction?.addEventListener('change',syncBulkCurrency);syncBulkCurrency();
</script>
</div>
@endsection
